/**
 * playerSprite.js — High-resolution F-22 Raptor stealth fighter sprite asset manager
 * 
 * Provides 512x612 transparent-background military F-22 Raptor sprite matching
 * the approved reference design (metallic grey body, glossy bright-blue canopy,
 * blue wing accents, and vivid cyan engine exhausts).
 */

const SPRITE_DATA_URI = 'data:image/png;base64,';

let f22Image = typeof Image !== 'undefined' ? new Image() : null;
let isLoaded = false;

if (f22Image) {
    // 1. Primary load from local assets folder
    f22Image.src = 'assets/player_f22.png';

    f22Image.onload = () => {
        isLoaded = true;
    };

    // 2. Fallback to embedded data URI if local relative load is blocked
    f22Image.onerror = () => {
        console.warn('[F22 Sprite] Local asset load deferred, using high-res data URI fallback.');
        f22Image = new Image();
        f22Image.onload = () => {
            isLoaded = true;
        };
        f22Image.src = SPRITE_DATA_URI;
    };
}

/**
 * Get the loaded F-22 Raptor image asset.
 * @returns {Image|null}
 */
export function getPlayerSprite() {
    return f22Image;
}

/**
 * Check if the F-22 sprite is ready to render.
 * @returns {boolean}
 */
export function isPlayerSpriteReady() {
    return !!(f22Image && f22Image.complete && f22Image.naturalWidth > 0);
}
